import itertools

def get_reachable_sets(N, k):
    # A set of k edges is defined by choosing k s_i and k b_i such that s_i < b_i
    # However, it's easier to just list all possible edges (s, b) with 1 <= s < b <= N.
    all_edges = []
    for s in range(1, N + 1):
        for b in range(s + 1, N + 1):
            all_edges.append((s, b))

    # Now we need to find sets of k edges E = {(s_1, b_1), ..., (s_k, b_k)}
    # such that s_1 < s_2 < ... < s_k and b_1 < b_2 < ... < b_k.
    # This is equivalent to choosing k edges such that they don't "cross" or "nest" in a certain way.
    # Wait, the condition s_1 < s_2 < ... < s_k and b_1 < b_2 < ... < b_k is what we need.

    possible_E = []
    for combo in itertools.combinations(all_edges, k):
        # combo is a tuple of k edges
        # sort them by s
        sorted_combo = sorted(list(combo))
        # Check if b's are strictly increasing
        b_vals = [e[1] for e in sorted_combo]
        if all(b_vals[i] < b_vals[i+1] for i in range(len(b_vals)-1)):
            possible_E.append(set(sorted_combo))

    reachable_sets = []
    for E in possible_E:
        # Compute reachability R
        # For small N, we can just use a simple reachability
        # But we need to know the stalls involved
        nodes = sorted(list(set([e[0] for e in E] + [e[1] for e in E])))
        node_map = {node: i for i, node in enumerate(nodes)}
        n = len(nodes)
        adj = [[False] * n for _ in range(n)]
        for s, b in E:
            adj[node_map[s]][node_map[b]] = True
        for m in range(n):
            for i in range(n):
                for j in range(n):
                    if adj[i][m] and adj[m][j]:
                        adj[i][j] = True
        R = set()
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    R.add((nodes[i], nodes[j]))
        reachable_sets.append(R)
    return reachable_sets

def solve_small(N):
    for k in range(1, N):
        reachable_sets = get_reachable_sets(N, k)
        # Check if there exist two reachable sets R1, R2 such that R1 \cap R2 = empty
        found_disjoint = False
        for i in range(len(reachable_sets)):
            for j in range(i, len(reachable_sets)):
                if reachable_sets[i].isdisjoint(reachable_sets[j]):
                    found_disjoint = True
                    break
            if found_disjoint:
                break

        if not found_disjoint:
            return k
    return None

for n in range(3, 8):
    print(f"N={n}, k={solve_small(n)}")

