def find_disjoint_R(N, k):
    all_edges = []
    for s in range(1, N + 1):
        for b in range(s + 1, N + 1):
            all_edges.append((s, b))

    possible_E = []
    for combo in itertools.combinations(all_edges, k):
        sorted_combo = sorted(list(combo))
        b_vals = [e[1] for e in sorted_combo]
        if all(b_vals[i] < b_vals[i+1] for i in range(len(b_vals)-1)):
            possible_E.append(set(sorted_combo))

    reachable_sets = [get_reachable(E) for E in possible_E]
    for i in range(len(reachable_sets)):
        for j in range(i, len(reachable_sets)):
            if reachable_sets[i].isdisjoint(reachable_sets[j]):
                return (reachable_sets[i], reachable_sets[j], possible_E[i], possible_E[j])
    return None

